import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as s,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"合并和排序 Linux 上的文件 | LCTT x X-CMD","titleTemplate":false,"description":"合并和排序 Linux 上的文件 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"合并和排序 Linux 上的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"合并和排序 Linux 上的文件 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200810 Merging and sorting files on Linux","title":"合并和排序 Linux 上的文件","tag":"202008","desc":""},"relativePath":"202008/20200810 Merging and sorting files on Linux.md","filePath":"[post].md"}'),h={name:"202008/20200810 Merging and sorting files on Linux.md"};function c(g,e,k,f,u,b){const a=p("Link");return o(),d("div",null,[e[15]||(e[15]=r(`<h1 id="合并和排序-linux-上的文件" tabindex="-1">合并和排序 Linux 上的文件 <a class="header-anchor" href="#合并和排序-linux-上的文件" aria-label="Permalink to “合并和排序 Linux 上的文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202008/22/102250i3943is48r34w4nz.jpg" alt=""></p><p>在 Linux 上合并和排序文本的方法有很多种，但如何去处理它取决于你试图做什么：你是只想将多个文件的内容放入一个文件中，还是以某种方式组织它，让它更易于使用。在本文中，我们将查看一些用于排序和合并文件内容的命令，并重点介绍结果有何不同。</p><h3 id="使用-cat" tabindex="-1">使用 cat <a class="header-anchor" href="#使用-cat" aria-label="Permalink to “使用 cat”">​</a></h3><p>如果你只想将一组文件放到单个文件中，那么 <code>cat</code> 命令是一个容易的选择。你所要做的就是输入 <code>cat</code>，然后按你希望它们在合并文件中的顺序在命令行中列出这些文件。将命令的输出重定向到要创建的文件。如果指定名称的文件已经存在，那么文件将被覆盖。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat firstfile secondfile thirdfile &gt; newfile</span></span></code></pre></div><p>如果要将一系列文件的内容添加到现有文件中，而不是覆盖它，只需将 <code>&gt;</code> 变成 <code>&gt;&gt;</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat firstfile secondfile thirdfile &gt;&gt; updated_file</span></span></code></pre></div><p>如果你要合并的文件遵循一些方便的命名约定，那么任务可能更简单。如果可以使用正则表达式指定所有文件名，那就不必列出所有文件。例如，如果文件全部以 <code>file</code> 结束，如上所示，你可以进行如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat *file &gt; allfiles</span></span></code></pre></div><p>请注意，上面的命令将按字母数字顺序添加文件内容。在 Linux 上，一个名为 <code>filea</code> 的文件将排在名为 <code>fileA</code> 的文件的前面，但会在 <code>file7</code> 的后面。毕竟，当我们处理字母数字序列时，我们不仅需要考虑 <code>ABCDE</code>，还需要考虑 <code>0123456789aAbBcCdDeE</code>。你可以使用 <code>ls *file</code> 这样的命令来查看合并文件之前文件的顺序。</p><p>注意：首先确保你的命令包含合并文件中所需的所有文件，而不是其他文件，尤其是你使用 <code>*</code> 等通配符时。不要忘记，用于合并的文件仍将单独存在，在确认合并后，你可能想要删除这些文件。</p><h3 id="按时间期限合并文件" tabindex="-1">按时间期限合并文件 <a class="header-anchor" href="#按时间期限合并文件" aria-label="Permalink to “按时间期限合并文件”">​</a></h3><p>如果要基于每个文件的时间期限而不是文件名来合并文件，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for file in \`ls -tr myfile.*\`; do  cat $file &gt;&gt; BigFile.$$; done</span></span></code></pre></div><p>使用 <code>-tr</code> 选项（<code>t</code> = 时间，<code>r</code> = 反向）将产生按照最早的在最前排列的文件列表。例如，如果你要保留某些活动的日志，并且希望按活动执行的顺序添加内容，则这非常有用。</p><p>上面命令中的 <code>$$</code> 表示运行命令时的进程 ID。不是很必要使用此功能，但它几乎不可能会无意添加到现有的文件，而不是创建新文件。如果使用 <code>$$</code>，那么生成的文件可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l BigFile.*</span></span>
<span class="line"><span>-rw-rw-r-- 1 justme justme   931725 Aug  6 12:36 BigFile.582914</span></span></code></pre></div><h3 id="合并和排序文件" tabindex="-1">合并和排序文件 <a class="header-anchor" href="#合并和排序文件" aria-label="Permalink to “合并和排序文件”">​</a></h3><p>Linux 提供了一些有趣的方式来对合并之前或之后的文件内容进行排序。</p><h4 id="按字母对内容进行排序" tabindex="-1">按字母对内容进行排序 <a class="header-anchor" href="#按字母对内容进行排序" aria-label="Permalink to “按字母对内容进行排序”">​</a></h4><p>如果要对合并的文件内容进行排序，那么可以使用以下命令对整体内容进行排序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.1 myfile.2 myfile.3 | sort &gt; newfile</span></span></code></pre></div><p>如果要按文件对内容进行分组，请使用以下命令对每个文件进行排序，然后再将它添加到新文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for file in \`ls myfile.?\`; do sort $file &gt;&gt; newfile; done</span></span></code></pre></div><h4 id="对文件进行数字排序" tabindex="-1">对文件进行数字排序 <a class="header-anchor" href="#对文件进行数字排序" aria-label="Permalink to “对文件进行数字排序”">​</a></h4><p>要对文件内容进行数字排序，请在 <code>sort</code> 中使用 <code>-n</code> 选项。仅当文件中的行以数字开头时，此选项才有用。请记住，按照默认顺序，<code>02</code> 将小于 <code>1</code>。当你要确保行以数字排序时，请使用 <code>-n</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.1 myfile.2 myfile.3 | sort -n &gt; xyz</span></span></code></pre></div><p>如果文件中的行以 <code>2020-11-03</code> 或 <code>2020/11/03</code>（年月日格式）这样的日期格式开头，<code>-n</code> 选项还能让你按日期对内容进行排序。其他格式的日期排序将非常棘手，并且将需要更复杂的命令。</p><h3 id="使用-paste" tabindex="-1">使用 paste <a class="header-anchor" href="#使用-paste" aria-label="Permalink to “使用 paste”">​</a></h3><p><code>paste</code> 命令允许你逐行连接文件内容。使用此命令时，合并文件的第一行将包含要合并的每个文件的第一行。以下是示例，其中我使用了大写字母以便于查看行的来源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file.a</span></span>
<span class="line"><span>A one</span></span>
<span class="line"><span>A two</span></span>
<span class="line"><span>A three</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ paste file.a file.b file.c</span></span>
<span class="line"><span>A one   B one   C one</span></span>
<span class="line"><span>A two   B two   C two</span></span>
<span class="line"><span>A three B three C thee</span></span>
<span class="line"><span>        B four  C four</span></span>
<span class="line"><span>                C five</span></span></code></pre></div><p>将输出重定向到另一个文件来保存它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ paste file.a file.b file.c &gt; merged_content</span></span></code></pre></div><p>或者，你可以将每个文件的内容在同一行中合并，然后将文件粘贴在一起。这需要使用 <code>-s</code>（序列）选项。注意这次的输出如何显示每个文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ paste -s file.a file.b file.c</span></span>
<span class="line"><span>A one   A two   A three</span></span>
<span class="line"><span>B one   B two   B three B four</span></span>
<span class="line"><span>C one   C two   C thee  C four  C five</span></span></code></pre></div><h3 id="使用-join" tabindex="-1">使用 join <a class="header-anchor" href="#使用-join" aria-label="Permalink to “使用 join”">​</a></h3><p>合并文件的另一个命令是 <code>join</code>。<code>join</code> 命令让你能基于一个共同字段合并多个文件的内容。例如，你可能有一个包含一组同事的电话的文件，其中，而另一个包含了同事的电子邮件地址，并且两者均按个人姓名列出。你可以使用 <code>join</code> 创建一个包含电话和电子邮件地址的文件。</p><p>一个重要的限制是文件的行必须是相同的顺序，并在每个文件中包括用于连接的字段。</p><p>这是一个示例命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ join phone_numbers email_addresses</span></span>
<span class="line"><span>Sandra 555-456-1234 bugfarm@gmail.com</span></span>
<span class="line"><span>Pedro 555-540-5405</span></span>
<span class="line"><span>John 555-333-1234 john_doe@gmail.com</span></span>
<span class="line"><span>Nemo 555-123-4567 cutie@fish.com</span></span></code></pre></div><p>在本例中，即使缺少附加信息，第一个字段（名字）也必须存在于每个文件中，否则命令会因错误而失败。对内容进行排序有帮助，而且可能更容易管理，但只要顺序一致，就不需要这么做。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在 Linux 上，你有很多可以合并和排序存储在单独文件中的数据的方式。这些方法可以使原本繁琐的任务变得异常简单。</p><hr>`,45)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3570508/merging-and-sorting-files-on-linux.html"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3570508/merging-and-sorting-files-on-linux.html",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const y=l(h,[["render",c]]);export{C as __pageData,y as default};
